import java.util.*;class RiverBankPatchTest{static EnvironmentMap land(int n,boolean patches){var e=new EnvironmentMap(EnvironmentMap.filled(n*n,95));e.water=EnvironmentMap.filled(n*n,62);e.river=new float[n*n];e.material=new byte[n*n];Arrays.fill(e.material,(byte)1);for(int z=0;z<n;z++)for(int x=0;x<n;x++){int i=z*n+x;if(patches)e.material[i]=(byte)(((x/8+z/8)%3)==0?10:7);if(x>=120&&x<=136){e.height[i]=82;e.water[i]=86;e.river[i]=1;e.material[i]=7;}}return e;}public static void main(String[]a){int n=256;var clean=land(n,false);var square=land(n,true);var node=new TerrainGraph.Node(1,TerrainGraph.Type.RIVER_BANKS,0,0);node.values.put("width",18.0);node.values.put("reach",224.0);RiverBanks.gradeValley(node,clean,n,n,62,2024,0,0,()->false);RiverBanks.gradeValley(node,square,n,n,62,2024,0,0,()->false);for(int z=0;z<n;z++)for(int x=0;x<n;x++){int i=z*n+x;if(square.material[i]!=clean.material[i])throw new AssertionError("Coarse square survived at "+x+","+z);if((x<80||x>176)&&square.material[i]!=1)throw new AssertionError("Sediment escaped narrow bank");}System.out.println("PASS: coarse square dirt/gravel patches replaced by full-resolution banks and grass; channel retained");}}
